-- ============================================================
--  Миграция 004: «Глюк-атака» — пятая игра
--
--  Что создаёт:
--    glitch_themes     — темы вопросов (цвет темы = цвет призрака в игре)
--    glitch_questions  — вопросы: текст, 4 варианта, номер верного (0..3),
--                        пояснение для разбора ошибок, флаг «скрыт»
--    games             — строка игры 'glitch' (каталог, карусель, админка)
--
--  Стартовые 50 вопросов — из викторины для мероприятия, переделанные
--  в формат «4 варианта». Правятся в админке: раздел «ГЛЮК-АТАКА».
--
--  Миграция идемпотентна (её запускает docker/entrypoint.sh при каждом
--  старте контейнера):
--    — таблицы создаются только если их нет;
--    — темы добавляются только отсутствующие (ON CONFLICT DO NOTHING),
--      правки названий и цветов из админки не перезаписываются;
--    — вопросы заливаются ТОЛЬКО в пустую таблицу. Если вопросы
--      правили или удаляли в админке, повторный запуск их не трогает.
--
--  Применить локально (Windows, свой PostgreSQL):
--    scripts\migrate-local.cmd
--  На сервере — автоматически после ./scripts/deploy.sh
--
--  Откат:
--    DROP TABLE IF EXISTS glitch_questions, glitch_themes;
--    DELETE FROM games WHERE id = 'glitch';
--  Очки игроков (scores с game_id = 'glitch') при этом остаются.
-- ============================================================

-- Файл в UTF-8; psql в консоли Windows иначе читает его как WIN1251.
SET client_encoding = 'UTF8';

BEGIN;

CREATE TABLE IF NOT EXISTS public.glitch_themes (
    id          varchar(20) PRIMARY KEY,
    name        varchar(40) NOT NULL,
    color       varchar(7)  NOT NULL DEFAULT '#00e5ff',
    sort_order  integer     NOT NULL DEFAULT 0,
    hidden      boolean     NOT NULL DEFAULT false,
    created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.glitch_questions (
    id           serial PRIMARY KEY,
    theme_id     varchar(20) NOT NULL REFERENCES public.glitch_themes(id) ON UPDATE CASCADE,
    question     text        NOT NULL,
    answer1      text        NOT NULL,
    answer2      text        NOT NULL,
    answer3      text        NOT NULL,
    answer4      text        NOT NULL,
    correct      smallint    NOT NULL DEFAULT 0 CHECK (correct BETWEEN 0 AND 3),
    explanation  text        NOT NULL DEFAULT '',
    hidden       boolean     NOT NULL DEFAULT false,
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_glitch_questions_theme ON public.glitch_questions (theme_id);

INSERT INTO public.glitch_themes (id, name, color, sort_order) VALUES
    ('net', 'СЕТИ', '#00e5ff', 10),
    ('python', 'PYTHON', '#39ff14', 20),
    ('pc', 'КОМПЬЮТЕР', '#f5d800', 30),
    ('linux', 'LINUX', '#ff8c1a', 40),
    ('data', 'ДАННЫЕ И ML', '#b24bff', 50),
    ('dev', 'РАЗРАБОТКА', '#ff4d6d', 60),
    ('web', 'ВЕБ И БД', '#4da3ff', 70)
ON CONFLICT (id) DO NOTHING;

-- Вопросы — только в пустую таблицу (см. шапку). Верный вариант в базе
-- всегда записан под своим номером; в игре варианты перемешивает сервер.
