-- Игра в каталоге: раздел «Практик», в конце порядка карусели.
INSERT INTO public.games (id, title, emoji, description, level, stars, wip, link, sort_order)
SELECT 'glitch', 'Глюк-атака', '👻',
       'Глюк-призраки атакуют сервер GameCode: отвечай на вопросы по IT и сбивай их из пушек.',
       'medium', 2, false, 'games/glitch/index.html',
       COALESCE((SELECT MAX(sort_order) + 1 FROM public.games), 0)
ON CONFLICT (id) DO NOTHING;

COMMIT;

ALTER TABLE public.glitch_themes OWNER TO gamecode_user;
ALTER TABLE public.glitch_questions OWNER TO gamecode_user;
